script:
Game.on('join', function (name) { Game.toast(name + ' joined the Gold Rush!'); });
Game.every(60, function () { Game.addMoney(25); Game.toast('Online bonus: +$25'); });
Game.on('buy', function (label) {
  if (label === 'Starter Kit') Game.toast('The money machine hums to life.');
  if (label === 'MEGA Dropper') Game.banner('A MEGA DROPPER roars to life!');
  if (label === 'Diamond Drops') Game.banner('DIAMOND DROPS! The mine sparkles.');
});
